//! 🔺️ Batched transforms transfer only actual prepared identifiers and admitted numeric bounds.
use crate::LayoutMutation;
use semio_s_artifact_layout_layout_diff::*;
use semio_s_artifact_layout_layout_model::snapshot::LayoutSnapshot;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneClose,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use super::batch_plan::FrameSelectionPlan;
use std::mem::{ManuallyDrop,size_of};
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"batch sparse output original custody is invalid")}
fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<LayoutDiff>()*3+size_of::<PageFramesModification>()*2+size_of::<LayoutMutation>()*2+512,depth:1,..Default::default()}}
fn input(m:&mut LayoutMutation)->Result<(&mut String,&mut Vec<String>),ValueError>{match m{LayoutMutation::DragFrames(p)=>Ok((&mut p.page_id,&mut p.targets)),LayoutMutation::RotateFrames(p)=>Ok((&mut p.page_id,&mut p.targets)),LayoutMutation::ScaleFrames(p)=>Ok((&mut p.page_id,&mut p.targets)),_=>Err(fault())}}
/// 🧳 Sparse partial rows stay owned before every fallible capacity check.
pub struct BatchOutput{diff:ManuallyDrop<Option<LayoutDiff>>,retirement:RetainedCloneClose,phase:u8,index:usize,payload:usize,targets:usize,closing:bool}
impl Default for BatchOutput{fn default()->Self{Self{diff:ManuallyDrop::new(Some(LayoutDiff::default())),retirement:Default::default(),phase:0,index:0,payload:0,targets:0,closing:false}}}
impl BatchOutput{
 pub fn demand(&self,plan:&FrameSelectionPlan,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>)->Result<RetirementDemand,ValueError>{plan.verify(m,b)?;if self.closing||!plan.ready()||plan.failure.is_some()||plan.changed().is_empty(){return Err(fault())}Ok(RetirementDemand{capacity_bytes:match self.phase{0=>size_of::<LayoutPagesModification>(),1=>plan.changed().len().checked_mul(size_of::<PageFramesModification>()).ok_or_else(fault)?,_=>0},..fixed()})}
 pub fn advance(&mut self,source:&mut Vec<LayoutMutation>,plan:&FrameSelectionPlan,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(plan,m,b)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let payload=source.last_mut().ok_or_else(fault)?;let address=payload as *mut LayoutMutation as usize;let kind=matches!(payload,LayoutMutation::RotateFrames(_));let scale=matches!(payload,LayoutMutation::ScaleFrames(_));let(page,targets)=input(payload)?;if self.phase>=2&&(self.payload!=address||self.targets!=targets.as_ptr()as usize){return Err(fault())}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};let diff=self.diff.as_mut().ok_or_else(fault)?;match self.phase{
 0=>{self.phase=254;diff.pages=Some(LayoutPagesDelta::default());let rows=&mut diff.pages.as_mut().unwrap().modified;let reserved=rows.try_reserve_exact(1);p.retained_capacity_bytes=rows.capacity()*size_of::<LayoutPagesModification>();if reserved.is_err()||p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(p))}rows.push(LayoutPagesModification{id:String::new(),patch:PagePatch::default()});self.phase=1},
 1=>{self.phase=254;let rows=&mut diff.pages.as_mut().unwrap().modified[0].patch.frames.modified;let reserved=rows.try_reserve_exact(plan.changed().len());p.retained_capacity_bytes=rows.capacity()*size_of::<PageFramesModification>();if reserved.is_err()||p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(p))}self.payload=address;self.targets=targets.as_ptr()as usize;self.phase=2},
 2=>{diff.pages.as_mut().unwrap().modified[0].id=std::mem::take(page);self.phase=3},
 3=>if let Some(row)=plan.changed().get(self.index){let values=row.bounds;let id=std::mem::take(targets.get_mut(row.target).ok_or_else(fault)?);diff.pages.as_mut().unwrap().modified[0].patch.frames.modified.push(PageFramesModification{id,patch:FramePatch{x:Some(values[0]),y:Some(values[1]),width:scale.then_some(values[2]),height:scale.then_some(values[3]),rotation:kind.then_some(values[4]),..Default::default()}});self.index+=1}else{self.phase=4},4=>{},_=>return Err(fault())}Ok(if self.phase==4{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn take_demand(&self)->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<LayoutDiff>>()*2,depth:1,..Default::default()}}
 pub fn take(&mut self,g:RetainedCloneGrant)->Result<(Option<LayoutDiff>,RetainedCloneProgress),ValueError>{if self.phase!=4||self.closing{return Err(fault())}let d=self.take_demand();if !retained_clone_grant_admits(g,d){return Ok((None,Default::default()))}self.phase=5;Ok((self.diff.take(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 pub fn begin_close(&mut self){self.closing=true}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{self.retirement.next_owner_demands::<LayoutDiff>(self.diff.is_some(),&None,body)}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(fault())}let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.retirement.is_empty(){return self.retirement.step_granted(g)}if let Some(step)=self.retirement.begin_granted(&mut self.diff,g)?{return Ok(RetainedCloneStep::Progress(step.progress()))}Ok(RetainedCloneStep::Complete(Default::default()))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.diff.is_none()&&self.retirement.is_empty()}
}
impl Drop for BatchOutput{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"batch sparse output needs original funded cleanup")}}
